from rest_framework import serializers
from rest_framework.exceptions import PermissionDenied
from .models import UserProfile, TenantMembership, OrganizationInvite

class TenantMembershipNestedSerializer(serializers.ModelSerializer):
    organization_id = serializers.IntegerField()

    class Meta:
        model = TenantMembership
        fields = ['organization_id', 'job_title']

class AccountProfileUpdateSerializer(serializers.ModelSerializer):
    membership = TenantMembershipNestedSerializer(required=False)

    class Meta:
        model = UserProfile
        fields = ['full_name', 'membership']

    def update(self, instance, validated_data):
        membership_data = validated_data.pop('membership', None)
        instance.full_name = validated_data.get('full_name', instance.full_name)
        instance.save()

        if membership_data:
            org_id = membership_data['organization_id']
            # Verify the user has a valid accepted invitation before linking to organization
            has_invite = OrganizationInvite.objects.filter(email=instance.user.email, organization_id=org_id, accepted=True).exists()
            if not has_invite:
                raise PermissionDenied("No approved invitation found for target organization.")
            TenantMembership.objects.update_or_create(
                user=instance.user,
                organization_id=org_id,
                defaults={'job_title': membership_data.get('job_title', 'Staff')}
            )
        return instance
